<div class="comment-list"><?php if(!$comentarios):?><p class="empty">Nenhum comentário adicionado.</p><?php else:?><?php foreach($comentarios as $comentario):?><article class="comment-card"><div><strong><?=e($comentario['autor']?:'Usuário removido')?></strong><time><?=e(dataHoraHistorico($comentario['criado_em']))?></time></div><p><?=nl2br(e($comentario['comentario']))?></p></article><?php endforeach;?><?php endif;?></div>
</div></section>
<section class="panel process-extra" id="anexos"><div class="panel-head"><div><h2>Anexos</h2><p>PDF, imagens, Word ou Excel, com até 10 MB por arquivo.</p></div></div><div class="extra-body">
