<div class="attachment-list"><?php if(!$anexos):?><p class="empty">Nenhum anexo enviado.</p><?php else:?><?php foreach($anexos as $anexo):?><article class="attachment-card"><div><strong><?=e($anexo['nome_original'])?></strong><small><?=e(tamanhoArquivo((int)$anexo['tamanho']))?> · <?=e($anexo['autor']?:'Usuário removido')?> · <?=e(dataHoraHistorico($anexo['criado_em']))?></small></div><a class="btn btn-ghost btn-sm" href="processo_anexo_baixar.php?id=<?=(int)$anexo['id']?>">Baixar</a></article><?php endforeach;?><?php endif;?></div>
</div></section>
</div>
<section class="panel audit-process"><div class="panel-head"><div><h2>Auditoria do processo</h2><p>Histórico cronológico desde o cadastro até a conclusão.</p></div></div><div class="process-timeline">
<?php if(!$temCadastro):?><article class="timeline-item"><span class="timeline-dot"></span><div class="timeline-card"><div class="timeline-head"><strong>Cadastro original</strong><time><?=e(dataHoraHistorico($processo['criado_em']))?></time></div><p>Processo cadastrado por <strong><?=e($processo['criador_nome']?:'usuário não disponível')?></strong>. Registro anterior à auditoria detalhada.</p></div></article><?php endif;?>
<?php foreach($historico as $h):$det=json_decode($h['detalhes']??'',true)?:[];$mudancas=$det['mudancas']??[];$dados=$det['dados']??[];?><article class="timeline-item"><span class="timeline-dot"></span><div class="timeline-card"><div class="timeline-head"><strong><?=e($acoes[$h['acao']]??ucfirst(str_replace('_',' ',$h['acao'])))?></strong><time><?=e(dataHoraHistorico($h['criado_em']))?></time></div><p>Realizado por <strong><?=e($h['ator']?:'Sistema/usuário removido')?></strong><?php if($h['ator']&&$h['efetivo']&&$h['ator']!==$h['efetivo']):?> usando a conta de <strong><?=e($h['efetivo'])?></strong><?php endif;?> · IP <?=e($h['ip']?:'não registrado')?></p>
<?php if($dados):?><div class="change-list"><?php foreach($dados as $campo=>$valor):?><div><span><?=e($rotulos[$campo]??$campo)?></span><strong><?=e(valorHistorico($valor))?></strong></div><?php endforeach;?></div><?php endif;?>
<?php if($mudancas):?><div class="change-list"><?php foreach($mudancas as $campo=>$valores):?><div><span><?=e($rotulos[$campo]??$campo)?></span><del><?=e(valorHistorico($valores['antes']??null))?></del><b>→</b><ins><?=e(valorHistorico($valores['depois']??null))?></ins></div><?php endforeach;?></div><?php elseif(!$dados&&empty($det)):?><p class="muted-text">Esta ação não possui detalhes adicionais.</p><?php endif;?></div></article><?php endforeach;?>
</div></section><?php require __DIR__.'/includes/footer.php';?>
